import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Comparison","description":"","frontmatter":{},"headers":[],"relativePath":"guide/comparison.md","filePath":"guide/comparison.md","lastUpdated":1787732804000}`),a={name:`guide/comparison.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to “Comparison”">​</a></h1><p>mcp-hub solves one specific problem: <strong>publishing stdio MCP servers to hosted clients over HTTPS, with OAuth, without one container per server.</strong> Plenty of setups do not have that problem. This page is about telling them apart.</p><h2 id="running-servers-locally-in-the-client" tabindex="-1">Running servers locally in the client <a class="header-anchor" href="#running-servers-locally-in-the-client" aria-label="Permalink to “Running servers locally in the client”">​</a></h2><p>Claude Code and Claude Desktop launch stdio servers themselves from a local config. Nothing is exposed, nothing needs a certificate, and the server can touch your local filesystem.</p><p><strong>Stay with this if</strong> every client you use runs on the machine that should run the servers.</p><p><strong>You outgrow it when</strong> you want the same servers from Claude Web, from a phone, or from more than one machine — none of which can start a process on your desktop.</p><h2 id="mcp-remote" tabindex="-1"><code>mcp-remote</code> <a class="header-anchor" href="#mcp-remote" aria-label="Permalink to “mcp-remote”">​</a></h2><p><a href="https://github.com/geelen/mcp-remote" target="_blank" rel="noreferrer"><code>mcp-remote</code></a> is a stdio bridge that lets a <em>local</em> client talk to a <em>remote</em> MCP server, handling the OAuth flow in a browser and caching the tokens.</p><p>It points the opposite way from mcp-hub: it adapts remote servers for local clients; mcp-hub adapts local servers for remote clients. They are complementary, not alternatives. mcp-hub no longer needs it for its own upstreams, though: it is an <a href="/guide/configuration#upstreams-that-speak-oauth">OAuth client in its own right</a> and obtains and refreshes those tokens itself.</p><p><strong>Use <code>mcp-remote</code> if</strong> your servers are already remote and your clients are local.</p><h2 id="one-auth-proxy-per-server" tabindex="-1">One auth proxy per server <a class="header-anchor" href="#one-auth-proxy-per-server" aria-label="Permalink to “One auth proxy per server”">​</a></h2><p>Wrap each stdio server in its own container with an OAuth or forward-auth proxy in front, one hostname each.</p><p><strong>This is genuinely better when</strong> your servers have <em>different</em> trust levels. Separate containers give separate filesystems, separate credentials and separate network policy. mcp-hub deliberately does not: every stdio child shares the hub&#39;s user and can read its state directory. That is the central trade-off, and it is why <a href="/guide/security#trust-model">SECURITY.md</a> says to put untrusted servers elsewhere and connect them as remote upstreams.</p><p><strong>mcp-hub is better when</strong> you trust the servers and are paying N× for images, certificates, OAuth stacks, log streams and re-authorizations that give you nothing extra.</p><p>You do not have to choose globally: run the sensitive ones separately and add them to the hub as <code>type: &quot;http&quot;</code> entries. From the client&#39;s side it is one setup either way.</p><h2 id="servers-that-already-speak-http" tabindex="-1">Servers that already speak HTTP <a class="header-anchor" href="#servers-that-already-speak-http" aria-label="Permalink to “Servers that already speak HTTP”">​</a></h2><p>A growing number of MCP servers ship their own Streamable-HTTP endpoint and their own authentication.</p><p><strong>You do not need a gateway for those.</strong> Point the client straight at them.</p><p>Two reasons people still route them through mcp-hub:</p><ul><li><strong>One connector.</strong> Adding them to <code>/hub</code> keeps the client&#39;s connector list and its context small.</li><li><strong>One authentication story.</strong> The hub holds the upstream credential — a header, or an OAuth token it obtained and refreshes itself — and presents its own OAuth outward, so a client never sees the upstream&#39;s token. An upstream that needs re-authorizing shows up as one server <code>unauthorized</code> in <code>/health</code> instead of a confusing 401 in the client.</li></ul><h2 id="hosted-or-commercial-mcp-gateways" tabindex="-1">Hosted or commercial MCP gateways <a class="header-anchor" href="#hosted-or-commercial-mcp-gateways" aria-label="Permalink to “Hosted or commercial MCP gateways”">​</a></h2><p>Managed gateways add things a single container does not have: multiple users and roles, audit trails, policy engines, SSO against a company directory, per-tool authorization.</p><p><strong>Choose one of those if</strong> you need any of that. mcp-hub has exactly one password and no notion of who is using it. It is built for one person or a small trusted group running their own infrastructure.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Local stdio</th><th><code>mcp-remote</code></th><th>Proxy per server</th><th>mcp-hub</th></tr></thead><tbody><tr><td>Reachable from hosted clients</td><td>no</td><td>n/a</td><td>yes</td><td>yes</td></tr><tr><td>Containers to operate</td><td>none</td><td>none</td><td>N</td><td>1</td></tr><tr><td>Certificates / hostnames</td><td>none</td><td>none</td><td>N</td><td>1</td></tr><tr><td>Logins to maintain</td><td>none</td><td>per server</td><td>N</td><td>1</td></tr><tr><td>Isolation between servers</td><td>n/a</td><td>n/a</td><td><strong>strong</strong></td><td>none (same user)</td></tr><tr><td>Context cost for N servers</td><td>N × tools</td><td>N × tools</td><td>N × tools</td><td>6 meta-tools via <code>/hub</code></td></tr><tr><td>Upstream OAuth handled for you</td><td>no</td><td>yes, per client</td><td>no</td><td>yes, per hub</td></tr><tr><td>Multi-user, roles, audit</td><td>no</td><td>no</td><td>depends</td><td>no</td></tr></tbody></table><p>If the isolation row is the one that matters for your setup, use separate containers — and let mcp-hub aggregate them over HTTP.</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};